{"command":"create","path":"/workspace/codebase/rust/src/main.rs","file_text":"use std::env;
use std::path::{Path, PathBuf};
use std::process::{Command, ExitCode};

fn package_root() -> PathBuf {
    if let Some(root) = env::var_os("JSCODESHIFT_PACKAGE_ROOT") {
        return PathBuf::from(root);
    }

    let executable = env::current_exe().ok();
    executable
        .as_deref()
        .and_then(|path| path.parent())
        .and_then(Path::parent)
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from(env!("CARGO_MANIFEST_DIR")))
}

fn main() -> ExitCode {
    let root = package_root();
    let bridge = root.join("bridge").join("transform-host.js");

    let status = match Command::new("node")
        .arg(&bridge)
        .args(env::args_os().skip(1))
        .env("JSCODESHIFT_PACKAGE_ROOT", &root)
        .status()
    {
        Ok(status) => status,
        Err(error) => {
            eprintln!("jscodeshift: unable to start the JavaScript compatibility bridge: {error}");
            return ExitCode::from(1);
        }
    };

    match status.code() {
        Some(code) if (0..=255).contains(&code) => ExitCode::from(code as u8),
        Some(_) => ExitCode::from(1),
        None => ExitCode::from(1),
    }
}
"}

